function meld(bili, inr, cr){
  bili=+bili; inr=+inr; cr=+cr;
  if([bili,inr,cr].some(function(v){return isNaN(v)||v<=0;})) return {error:'胆红素/INR/肌酐须为正'};
  var B=Math.max(bili,1), I=Math.max(inr,1), C=Math.max(Math.min(cr,4),1);
  var s=3.78*Math.log(B)+11.2*Math.log(I)+9.57*Math.log(C)+6.43;
  s=Math.max(0,Math.round(s*10)/10);
  var interp;
  if(s>=40) interp='3 个月病死风险很高（≥40）';
  else if(s>=30) interp='3 个月病死风险高（30–39）';
  else if(s>=20) interp='3 个月病死风险中等（20–29）';
  else if(s>=10) interp='3 个月病死风险较低（10–19）';
  else interp='3 个月病死风险低（<10）';
  return {meld:s, interp:interp, note:'MELD 评分，非医疗建议'};
}
var EXPORTS={meld:meld};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MeldForgePure = EXPORTS; }
